        // 3. 自动判定体态（根据三围和性别）
        function classifyBodyType(gender, bust, waist, hip) {
            const waistHipRatio = waist / hip;
            const bustWaistRatio = bust / waist;
            if (gender === '女') {
                if (waistHipRatio < 0.7 && bustWaistRatio > 1.2) return '沙漏型';
                if (waistHipRatio > 0.8 && bustWaistRatio < 1.1) return '梨型';
                if (bust > 100 && hip > 100) return '丰满型';
                if (bust < 80 && waist < 60 && hip < 85) return '纤细型';
            } else {
                if (waist < 70) return '精瘦型';
                if (waist > 90) return '壮实型';
            }
            return '标准';
        }

