        // 11. 添加妆容详情
        function addMakeupDetail() {
            const part = makeupPartSelect.value;
            const style = makeupStyleSelect.value;
            const color = makeupColorSelect.value;
            const partCustom = part === '自定义' ? makeupPartCustom.value.trim() : '';
            const styleCustom = style === '自定义' ? makeupStyleCustom.value.trim() : '';
            const colorCustom = color === '自定义' ? makeupColorCustom.value.trim() : '';
            if (part === '自定义' && !partCustom) {
                alert('请输入自定义部位');
                return;
            }
            if (style === '自定义' && !styleCustom) {
                alert('请输入自定义样式');
                return;
            }
            if (color === '自定义' && !colorCustom) {
                alert('请输入自定义颜色');
                return;
            }
            send_context.makeupDetails.push({ part, partCustom, style, styleCustom, color, colorCustom });
            renderMakeupList();
            updateMakeupSummary();
            updateCurrentDisplays();
            makeupPartSelect.selectedIndex = 0;
            makeupStyleSelect.selectedIndex = 0;
            makeupColorSelect.selectedIndex = 0;
            toggleCustomInput(makeupPartSelect, makeupPartCustom);
            toggleCustomInput(makeupStyleSelect, makeupStyleCustom);
            toggleCustomInput(makeupColorSelect, makeupColorCustom);
        }

        // 12. 格式化妆容详情文本
        function formatMakeupDetails(details) {
            if (!details || details.length === 0) return '';
            return details.map(item => {
                const partText = item.part === '自定义' ? `自定义(${item.partCustom || '未填写'})` : item.part;
                const styleText = item.style === '自定义' ? `自定义(${item.styleCustom || '未填写'})` : item.style;
                const colorText = item.color === '自定义' ? `自定义(${item.colorCustom || '未填写'})` : item.color;
                return `${partText}：${styleText} / ${colorText}`;
            }).join('，');
        }

        // 12.1 格式化体毛详情文本
        function formatBodyHairDetails(details) {
            if (!details || details.length === 0) return '';
            return details.map(item => {
                const ptxt = item.pattern === '自定义' ? `自定义(${item.custom || '未填写'})` : item.pattern;
                return `${item.part}：${item.density}/${ptxt}`;
            }).join('，');
        }

        // 12.2 格式化纹身/烙印详情文本
        function formatTattooDetails(details) {
            if (!details || details.length === 0) return '';
            return details.map(t => {
                const ptxt = t.pattern === '自定义' ? `自定义(${t.custom || '未填写'})` : t.pattern;
                return `${t.part}的${t.form}(${ptxt})`;
            }).join('，');
        }

