        // 15.1 构建最终发送消息文本（基于当前上下文）
        function buildFinalMessageFromContext() {
            const g = send_context.gender || '随机';
            const age = send_context.years_old || '随机（8岁~32岁）';
            const idt = send_context.identity || '未选择';
