        // 1. 渲染选项按钮（如性别、身份）
        function renderOptions(container, dataList, key, isPonygirl = false, isMaster = false) {
            container.innerHTML = '';
            dataList.forEach(item => {
                const btn = document.createElement('div');
                btn.className = 'option-item';
                btn.textContent = item;
                // 根据上下文判断选中状态
                const isSelected = isPonygirl
                    ? send_context.ponygirlInfo[key] === item
                    : isMaster
                        ? send_context.masterInfo[key] === item
                        : send_context[key] === item;
                if (isSelected) btn.classList.add('selected');
                // 点击事件：更新选中状态和上下文
                btn.addEventListener('click', () => {
                    container.querySelectorAll('.option-item').forEach(b => b.classList.remove('selected'));
                    btn.classList.add('selected');
                    if (isPonygirl) {
                        send_context.ponygirlInfo[key] = item;
                    } else if (isMaster) {
                        send_context.masterInfo[key] = item;
                    } else {
                        send_context[key] = item;
                    }
                    // 开局选项：当选择“自定义”时，显示对应输入框并以输入值更新开局
                    if (key === 'opening') {
                        const isPony = container.id === 'opening-ponygirl-select';
                        const isMas = container.id === 'opening-master-select';
                        const ccId = isPony ? 'opening-ponygirl-custom-container' : (isMas ? 'opening-master-custom-container' : null);
                        const ciId = isPony ? 'opening-ponygirl-custom-input' : (isMas ? 'opening-master-custom-input' : null);
                        if (ccId && ciId) {
                            const cc = document.getElementById(ccId);
                            const ci = document.getElementById(ciId);
                            if (item === '自定义') {
                                cc.style.display = 'block';
                                ci.focus();
                                // 若当前无输入，则暂存为“自定义”，输入时会实时更新
                                send_context.opening = (ci.value || '').trim() || '自定义';
                            } else {
                                cc.style.display = 'none';
                                send_context.opening = item;
                            }
                        }
                    }
                    // 身份变更时切换页面3的内容（母马/主人）
                    if (key === 'identity') handlePageNavigation(currentRegularPage);
                    updateCurrentDisplays();
                });
                container.appendChild(btn);
            });
        }

