        // 6. 同步三围滑块与上下文（修复体态计算）
        function syncBodyUIFromContext({ recompute = false }) {
            const { bust, waist, hip, height, weight } = send_context.body;
            // 同步页面2的滑块与数字框
            const sync = (rangeId, numberId, value) => {
                const range = document.getElementById(rangeId);
                const number = document.getElementById(numberId);
                range.value = value;
                number.value = value;
                // 绑定同步事件
                range.addEventListener('input', () => {
                    number.value = range.value;
                    send_context.body[rangeId.replace('-range', '')] = parseInt(range.value);
                    updateBodyType();
                });
                number.addEventListener('input', () => {
                    const val = Math.min(parseInt(number.value) || range.min, range.max);
                    range.value = val;
                    send_context.body[rangeId.replace('-range', '')] = val;
                    updateBodyType();
                });
            };
            sync('bust-range', 'bust-number', bust);
            sync('waist-range', 'waist-number', waist);
            sync('hip-range', 'hip-number', hip);
            sync('height-range', 'height-number', height);
            sync('weight-range', 'weight-number', weight);
            // 重新计算体态
            if (recompute) updateBodyType();
        }

