        // 15.1 构建最终发送消息文本（基于当前上下文）
        function buildFinalMessageFromContext() {
            const g = send_context.gender || '随机';
            const age = send_context.years_old || '随机（8岁~32岁）';
            const idt = send_context.identity || '未选择';
            const appearance = send_context.appearance || '随机';
            const skin = send_context.skinColor || '随机';
            const hairColor = send_context.hairColor || '随机';
            const hairStyle = send_context.hairStyle || '随机';
            const hairLength = send_context.hairLength || '随机';
            const eye = send_context.eyeColor || '随机';
            const face = send_context.faceShape || '随机';
            const bodyType = send_context.bodyType || '随机';
            const b = send_context.body || {};
            const hasBody = Number.isFinite(b.bust) && Number.isFinite(b.waist) && Number.isFinite(b.hip);
            const measureText = hasBody
                ? `三围: ${b.bust || '-'}-${b.waist || '-'}-${b.hip || '-'} cm, 身高: ${b.height || '-'} cm, 体重: ${b.weight || '-'} kg`
                : `三围/身高/体重: 随机`;
            const makeup = formatMakeupDetails(send_context.makeupDetails) || '未设置';
            const tattoo = (send_context.tattoos && send_context.tattoos.length > 0)
                ? send_context.tattoos.map(t => `${t.part}的${t.form}${t.pattern === '自定义' ? `(${t.custom || ''})` : `(${t.pattern})`}`).join('，')
                : '无';

            let lines = [];
            lines.push('{{user}}角色设定:');
            lines.push(`性别: ${g}`);
            lines.push(`年龄: ${age}`);
            lines.push(`身份: ${idt}`);
            lines.push(`外貌: 容貌${appearance} / 肤色${skin} / 发色${hairColor} / 发型${hairStyle} / 发长${hairLength} / 瞳色${eye} / 脸型${face}`);
            lines.push(`体态: ${bodyType}（${measureText}）`);
            lines.push(`妆容: ${makeup}`);
            const bodyhair = formatBodyHairDetails(send_context.bodyHairDetails) || '未设置';
            lines.push(`体毛: ${bodyhair}`);
            lines.push(`纹身/烙印: ${tattoo}`);

            if (idt === '母马') {
                const lvl = send_context.ponygirlInfo.level || '随机';
                const belong = send_context.ponygirlInfo.belong || '随机';
                const pts = send_context.ponygirlInfo.points || '随机';
                const legend = send_context.isLegendPonygirl ? (send_context.legendPonygirlName || '传奇母马') : '非传奇母马';
                lines.push(`母马等级: ${lvl}`);
                lines.push(`母马归属: ${belong}`);
                lines.push(`母马积分: ${pts}`);
                lines.push(`传奇: ${legend}`);
            } else if (idt === '主人') {
                const asset = send_context.masterInfo.asset || '随机';
                const role = send_context.masterInfo.role || '随机';
                lines.push(`主人资产: ${asset}`);
                lines.push(`主人身份: ${role}`);
                const ponyList = send_context.masterInfo.ownedPonygirls || [];
                if (ponyList.length > 0) {
                    const brief = ponyList.map((p, idx) => {
                        const n = p.name || `母马${idx + 1}`;
                        const lv = p.level || '-';
                        const ps = p.points || '-';
                        const bt = p.bodyType || '-';
                        return `${idx + 1}. ${n}（等级:${lv} / 积分:${ps} / 体态:${bt}）`;
                    }).join('\n');
                    lines.push('名下母马:');
                    lines.push(brief);
                }
            }

            // 开局
            const openingText = send_context.opening || '未选择';
            lines.push(`开局: ${openingText}`);

            return lines.join('\n');
        }

