        // 17. 处理页面导航
        function handlePageNavigation(targetPage) {
            if (targetPage < 1 || targetPage > total_pages) return;
            currentRegularPage = targetPage;

            regularPages.forEach(page => page.classList.remove('active'));

            if (currentRegularPage === 3) {
                if (send_context.identity === "母马") {
                    page3_1.classList.add('active');
                } else if (send_context.identity === "主人") {
                    page3_2.classList.add('active');
                } else {
                    page3.classList.add('active');
                }
            } else if (currentRegularPage === 4) {
                if (send_context.identity === "母马") {
                    page4_1.classList.add('active');
                } else if (send_context.identity === "主人") {
                    page4_2.classList.add('active');
                } else {
                    page4.classList.add('active');
                }
            } else {
                document.getElementById(`page${currentRegularPage}`).classList.add('active');
            }

            prevBtn.disabled = currentRegularPage === 1;
            nextBtn.disabled = currentRegularPage === total_pages;
            pageInfo.textContent = `第 ${currentRegularPage} 页 / 共 ${total_pages} 页`;
            updateCurrentDisplays();
        }

