        // 21. 渲染预设列表
        function renderPresetList() {
            const presets = JSON.parse(localStorage.getItem('ponygirlPresets') || '{}');
            const keys = Object.keys(presets);
            presetList.innerHTML = '';

            if (keys.length === 0) {
                const empty = document.createElement('div');
                empty.className = 'preset-item';
                empty.style.color = '#94A3B8';
                empty.style.textAlign = 'center';
                empty.textContent = '暂无已保存的预设';
                presetList.appendChild(empty);
                selectedPresetName = '';
                updatePresetPreview();
                updateDeleteBtnState();
                return;
            }

            keys.forEach(key => {
                const item = document.createElement('div');
                item.className = 'preset-item';
                item.textContent = key;
                if (key === selectedPresetName) {
                    item.classList.add('selected');
                }
                item.addEventListener('click', () => {
                    selectedPresetName = key;
                    renderPresetList();
                    updatePresetPreview();
                    updateDeleteBtnState();
                });
                presetList.appendChild(item);
            });
        }

        // 22. 更新预设预览
        function updatePresetPreview() {
            if (!selectedPresetName) {
                presetPreview.innerHTML = '<div class="display-item">未选中任何预设</div>';
                return;
            }

            const presets = JSON.parse(localStorage.getItem('ponygirlPresets') || '{}');
            const preset = presets[selectedPresetName];
            if (!preset) {
                presetPreview.innerHTML = '<div class="display-item">预设数据不存在</div>';
                return;
            }

            // 临时保存当前上下文，用于预览
            const tempContext = { ...send_context };
            // 应用预设数据
            Object.assign(send_context, preset);
            // 生成预览HTML
            let previewHTML = getCurrentDisplayHTML();
            if (send_context.identity === "母马") {
                previewHTML = getPonygirlDisplayHTML();
            } else if (send_context.identity === "主人") {
                previewHTML = getMasterDisplayHTML();
            }
            presetPreview.innerHTML = previewHTML;
            // 恢复原始上下文
            Object.assign(send_context, tempContext);
        }

        // 23. 保存当前选项为预设
        function saveAsPreset() {
            const presetName = prompt('请输入预设名称：', '新预设');
            if (!presetName || presetName.trim() === '') {
                showPresetTip('预设名称不能为空', 'error');
                return;
            }

            const presets = JSON.parse(localStorage.getItem('ponygirlPresets') || '{}');
            // 深拷贝当前上下文
            const presetData = JSON.parse(JSON.stringify(send_context));
            presets[presetName] = presetData;
            localStorage.setItem('ponygirlPresets', JSON.stringify(presets));

            selectedPresetName = presetName;
            renderPresetList();
            updatePresetPreview();
            updateDeleteBtnState();
            showPresetTip(`预设「${presetName}」已保存`);
        }

        // 24. 删除选中预设
        function deleteSelectedPreset() {
            if (!selectedPresetName) return;

            if (!confirm(`确定要删除预设「${selectedPresetName}」吗？`)) {
                return;
            }

            const presets = JSON.parse(localStorage.getItem('ponygirlPresets') || '{}');
            delete presets[selectedPresetName];
            localStorage.setItem('ponygirlPresets', JSON.stringify(presets));

            selectedPresetName = '';
            renderPresetList();
            updatePresetPreview();
            updateDeleteBtnState();
            showPresetTip(`预设已删除`);
        }

        // 25. 读取选中预设
        function loadSelectedPreset() {
            if (!selectedPresetName) {
                showPresetTip('请先选择一个预设', 'error');
                return;
            }

            const presets = JSON.parse(localStorage.getItem('ponygirlPresets') || '{}');
            const preset = presets[selectedPresetName];
            if (!preset) {
                showPresetTip('预设数据不存在', 'error');
                return;
            }

            // 深拷贝预设数据到上下文
            Object.assign(send_context, JSON.parse(JSON.stringify(preset)));

            // 更新UI
            updateUIFromContext();
            backToRegularPage();
            showPresetTip(`已加载预设「${selectedPresetName}」`);
        }

        // 26. 从上下文更新UI
        function updateUIFromContext() {
            // 更新选项按钮选中状态
            updateOptionButtonStates();
            // 更新下拉选择框
            years_old_select.value = send_context.years_old || years_old_list[0];
            // 更新三围滑块
            syncBodyUIFromContext({ recompute: true });
            // 更新传奇母马选项
            legend_ponygirl_checkbox.checked = send_context.isLegendPonygirl;
            legend_ponygirl_input.value = send_context.legendPonygirlName;
            legend_ponygirl_input.classList.toggle('visible', send_context.isLegendPonygirl);
            // 更新妆容和纹身
            updateMakeupSummary();
            updateTattooSummary();
            updateBodyHairSummary();
            // 更新名下母马摘要
            const ponyList = send_context.masterInfo.ownedPonygirls || [];
            ownedPonygirlsSummary.textContent = ponyList.length > 0
                ? `共${ponyList.length}匹：${ponyList.map(p => p.name).join('、')}`
                : '当前无名下母马';
            // 更新显示
            updateCurrentDisplays();
        }

        // 27. 更新选项按钮选中状态
        function updateOptionButtonStates() {
            // 性别
            setOptionButtonSelected(gender_select, send_context.gender);
            // 身份
            setOptionButtonSelected(identity_select, send_context.identity);
            // 容貌
            setOptionButtonSelected(appearance_select, send_context.appearance);
            // 肤色
            setOptionButtonSelected(skinColor_select, send_context.skinColor);
            // 发色
            setOptionButtonSelected(hairColor_select, send_context.hairColor);
            // 发型
            setOptionButtonSelected(hairStyle_select, send_context.hairStyle);
            // 发长
            setOptionButtonSelected(hairLength_select, send_context.hairLength);
            // 瞳色
            setOptionButtonSelected(eyeColor_select, send_context.eyeColor);
            // 脸型
            setOptionButtonSelected(faceShape_select, send_context.faceShape);
            // 母马等级
            setOptionButtonSelected(ponygirl_level_select, send_context.ponygirlInfo.level);
            // 母马归属
            setOptionButtonSelected(ponygirl_belong_select, send_context.ponygirlInfo.belong);
            // 母马积分
            setOptionButtonSelected(ponygirl_points_select, send_context.ponygirlInfo.points);
            // 主人资产
            setOptionButtonSelected(master_asset_select, send_context.masterInfo.asset);
            // 主人身份
            setOptionButtonSelected(master_identity_select, send_context.masterInfo.role);
        }

        // 28. 设置选项按钮选中状态
        function setOptionButtonSelected(container, value) {
            const buttons = container.querySelectorAll('.option-item');
            buttons.forEach(btn => {
                if (btn.textContent === value) {
                    btn.classList.add('selected');
                } else {
                    btn.classList.remove('selected');
                }
            });
        }

        // 29. 更新妆容摘要
        function updateMakeupSummary() {
            const details = send_context.makeupDetails || [];
            if (details.length === 0) {
                makeupSummary.textContent = '当前未设置妆容';
                return;
            }
            makeupSummary.textContent = formatMakeupDetails(details);
        }

        // 30. 更新纹身摘要
        function updateTattooSummary() {
            const tattoos = send_context.tattoos || [];
            if (tattoos.length === 0) {
                tattooSummary.textContent = '当前无纹身/烙印';
                return;
            }
            tattooSummary.textContent = tattoos.map(t => {
                const ptxt = t.pattern === '自定义' ? `自定义(${t.custom || '未填写'})` : t.pattern;
                return `${t.part}的${t.form}(${ptxt})`;
            }).join('，');
        }

        // 30.1 更新体毛摘要
        function updateBodyHairSummary() {
            const list = send_context.bodyHairDetails || [];
            if (list.length === 0) {
                if (bodyHairSummary) bodyHairSummary.textContent = '当前未设置体毛';
                return;
            }
            if (bodyHairSummary) bodyHairSummary.textContent = formatBodyHairDetails(list);
        }

        // 31. 显示预设提示
        function showPresetTip(message, type = 'info') {
            presetTip.textContent = message;
            presetTip.style.backgroundColor = type === 'error' ? '#7a2e2e' : 'rgba(0, 0, 0, 0.8)';
            presetTip.style.display = 'block';
            setTimeout(() => {
                presetTip.style.display = 'none';
            }, 2000);
        }

        // 32. 初始化纹身模态框
        function initTattooModal() {
            // 填充纹身选项
            tattoo_parts.forEach(part => {
                const opt = document.createElement('option');
                opt.value = part;
                opt.textContent = part;
                tattooPartSelect.appendChild(opt);
            });
            tattoo_forms.forEach(form => {
                const opt = document.createElement('option');
                opt.value = form;
                opt.textContent = form;
                tattooTypeSelect.appendChild(opt);
            });
            tattoo_patterns.forEach(pattern => {
                const opt = document.createElement('option');
                opt.value = pattern;
                opt.textContent = pattern;
                tattooPatternSelect.appendChild(opt);
            });

            // 自定义图案输入框显示控制
            tattooPatternSelect.addEventListener('change', () => {
                toggleCustomInput(tattooPatternSelect, tattooPatternCustom);
            });

            // 添加纹身按钮事件
            tattooAddBtn.addEventListener('click', () => {
                const part = tattooPartSelect.value;
                const form = tattooTypeSelect.value;
                const pattern = tattooPatternSelect.value;
                const custom = pattern === '自定义' ? tattooPatternCustom.value.trim() : '';

                if (pattern === '自定义' && !custom) {
                    alert('请输入自定义图案');
                    return;
                }

                if (!send_context.tattoos) send_context.tattoos = [];
                send_context.tattoos.push({ part, form, pattern, custom });
                renderTattooList();
                updateTattooSummary();
                updateCurrentDisplays();

                // 重置表单
                tattooPatternSelect.selectedIndex = 0;
                toggleCustomInput(tattooPatternSelect, tattooPatternCustom);
                tattooPatternCustom.value = '';
            });

            // 打开纹身模态框
            tattooEditBtn.addEventListener('click', () => {
                renderTattooList();
                tattooModal.style.display = 'flex';
            });

            // 关闭纹身模态框
            tattooDoneBtn.addEventListener('click', () => {
                tattooModal.style.display = 'none';
            });
        }

        // 33. 初始化妆容模态框
        function initMakeupModal() {
            // 填充妆容选项
            makeup_parts.forEach(part => {
                const opt = document.createElement('option');
                opt.value = part;
                opt.textContent = part;
                makeupPartSelect.appendChild(opt);
            });
            makeup_styles.forEach(style => {
                const opt = document.createElement('option');
                opt.value = style;
                opt.textContent = style;
                makeupStyleSelect.appendChild(opt);
            });
            makeup_colors.forEach(color => {
                const opt = document.createElement('option');
                opt.value = color;
                opt.textContent = color;
                makeupColorSelect.appendChild(opt);
            });

            // 自定义输入框显示控制
            makeupPartSelect.addEventListener('change', () => {
                toggleCustomInput(makeupPartSelect, makeupPartCustom);
            });
            makeupStyleSelect.addEventListener('change', () => {
                toggleCustomInput(makeupStyleSelect, makeupStyleCustom);
            });
            makeupColorSelect.addEventListener('change', () => {
                toggleCustomInput(makeupColorSelect, makeupColorCustom);
            });

            // 添加妆容按钮事件
            makeupAddBtn.addEventListener('click', addMakeupDetail);

            // 打开妆容模态框
            makeupEditBtn.addEventListener('click', () => {
                renderMakeupList();
                makeupModal.style.display = 'flex';
            });

            // 关闭妆容模态框
            makeupDoneBtn.addEventListener('click', () => {
                makeupModal.style.display = 'none';
            });
        }

        // 33.1 初始化体毛模态框
        function initBodyHairModal() {
            // 填充体毛选项
            bodyhair_parts.forEach(part => {
                const opt = document.createElement('option');
                opt.value = part;
                opt.textContent = part;
                bodyHairPartSelect.appendChild(opt);
            });
            bodyhair_density_list.forEach(d => {
                const opt = document.createElement('option');
                opt.value = d;
                opt.textContent = d;
                bodyHairDensitySelect.appendChild(opt);
            });
            bodyhair_patterns.forEach(p => {
                const opt = document.createElement('option');
                opt.value = p;
                opt.textContent = p;
                bodyHairPatternSelect.appendChild(opt);
            });

            // 自定义样式显示控制
            bodyHairPatternSelect.addEventListener('change', () => {
                toggleCustomInput(bodyHairPatternSelect, bodyHairPatternCustom);
            });

            // 添加体毛按钮事件
            bodyHairAddBtn.addEventListener('click', () => {
                const part = bodyHairPartSelect.value;
                const density = bodyHairDensitySelect.value;
                const pattern = bodyHairPatternSelect.value;
                const custom = pattern === '自定义' ? bodyHairPatternCustom.value.trim() : '';

                if (pattern === '自定义' && !custom) {
                    alert('请输入自定义样式/图案');
                    return;
                }

                if (!send_context.bodyHairDetails) send_context.bodyHairDetails = [];
                send_context.bodyHairDetails.push({ part, density, pattern, custom });
                renderBodyHairList();
                updateBodyHairSummary();
                updateCurrentDisplays();

                // 重置
                bodyHairPatternSelect.selectedIndex = 0;
                toggleCustomInput(bodyHairPatternSelect, bodyHairPatternCustom);
                bodyHairPatternCustom.value = '';
            });

            // 打开体毛模态框
            bodyHairEditBtn.addEventListener('click', () => {
                renderBodyHairList();
                bodyHairModal.style.display = 'flex';
            });

            // 关闭体毛模态框
            bodyHairDoneBtn.addEventListener('click', () => {
                bodyHairModal.style.display = 'none';
            });
        }

        // 34. 初始化所有选项和事件
        function init() {
            // 渲染选项按钮
            renderOptions(gender_select, gender_list, 'gender');
            renderOptions(identity_select, identity_list, 'identity');
            renderOptions(appearance_select, appearance_list, 'appearance');
            renderOptions(skinColor_select, skinColor_list, 'skinColor');
            renderOptions(hairColor_select, hairColor_list, 'hairColor');
            renderOptions(hairStyle_select, hairStyle_list, 'hairStyle');
            renderOptions(hairLength_select, hairLength_list, 'hairLength');
            renderOptions(eyeColor_select, eyeColor_list, 'eyeColor');
            renderOptions(faceShape_select, faceShape_list, 'faceShape');
            renderOptions(ponygirl_level_select, ponygirl_level_list, 'level', true);
            renderOptions(ponygirl_belong_select, ponygirl_belong_list, 'belong', true);
            renderOptions(ponygirl_points_select, ponygirl_points_list, 'points', true);
            renderOptions(master_asset_select, master_asset_list, 'asset', false, true);
            renderOptions(master_identity_select, master_identity_list, 'role', false, true);
            // 开局选项
            renderOptions(document.getElementById('opening-ponygirl-select'), opening_ponygirl_list, 'opening');
            renderOptions(document.getElementById('opening-master-select'), opening_master_list, 'opening');

            // 自定义开局输入事件：在对应容器显示时实时同步到上下文
            const openingPonyCustomContainer = document.getElementById('opening-ponygirl-custom-container');
            const openingPonyCustomInput = document.getElementById('opening-ponygirl-custom-input');
            const openingMasterCustomContainer = document.getElementById('opening-master-custom-container');
            const openingMasterCustomInput = document.getElementById('opening-master-custom-input');
            if (openingPonyCustomInput) {
                openingPonyCustomInput.addEventListener('input', () => {
                    if (openingPonyCustomContainer && openingPonyCustomContainer.style.display !== 'none') {
                        send_context.opening = openingPonyCustomInput.value.trim() || '自定义';
                        updateCurrentDisplays();
                    }
                });
            }
            if (openingMasterCustomInput) {
                openingMasterCustomInput.addEventListener('input', () => {
                    if (openingMasterCustomContainer && openingMasterCustomContainer.style.display !== 'none') {
                        send_context.opening = openingMasterCustomInput.value.trim() || '自定义';
                        updateCurrentDisplays();
                    }
                });
            }

            // 初始化下拉选择框
            initSelect(years_old_select, years_old_list, 'years_old');

            // 初始化三围滑块
            syncBodyUIFromContext({ recompute: true });

            // 初始化传奇母马组件
            initLegendComponent();

            // 初始化名下母马组件
            initMasterPonyComponent();

            // 初始化纹身模态框
            initTattooModal();

            // 初始化妆容模态框
            initMakeupModal();

            // 初始化体毛模态框
            initBodyHairModal();

            // 页面导航事件
            prevBtn.addEventListener('click', () => handlePageNavigation(currentRegularPage - 1));
            nextBtn.addEventListener('click', () => handlePageNavigation(currentRegularPage + 1));
            gotoPresetBtn.addEventListener('click', goToPresetPage);
            backToRegularBtn.addEventListener('click', backToRegularPage);

            // 预设管理事件
            saveAsPresetBtn.addEventListener('click', saveAsPreset);
            deleteSelectedPresetBtn.addEventListener('click', deleteSelectedPreset);
            loadSelectedPresetBtn.addEventListener('click', loadSelectedPreset);

            // 发送按钮事件
            if (sendBtn) {
                sendBtn.addEventListener('click', () => {
                    const finalMessage = buildFinalMessageFromContext();
                    try {
                        if (typeof triggerSlash === 'function') {
                            triggerSlash(`/send ${finalMessage}|/trigger`);
                            alert('角色设定已发送！\n建议在AI首次输出完毕后刷新页面，以隐藏设定界面。');
                        } else {
                            throw new Error('未找到 triggerSlash 函数');
                        }
                    } catch (error) {
                        console.error('发送失败:', error);
                        alert(`启动冒险时发生错误: ${error.message}\n请检查SillyTavern脚本环境是否正常。`);
                    }
                });
            }

            // 初始化显示
            updateCurrentDisplays();
            updateBodyHairSummary();
            // 默认显示第1页
            handlePageNavigation(1);
        }

        // 启动应用
        init();
    </script>
</body>
</html>

